import {
    DEFAULT_TEST_DURATION,
    DEFAULT_TEST_FPS,
    DEFAULT_TEST_RESOLUTION,
    MAX_TEST_DURATION,
    MIN_TEST_DURATION,
    TEST_DURATION_STEP,
    TEST_FPS_OPTIONS,
    VIDEO_RESOLUTION_OPTIONS,
} from '@gsm-app/constants';
import { useBuildSearch } from '@gsm-app/hooks/useBuildSearch';
import { useFeature } from '@gsm-app/hooks/useFeature';
import { useModalOnClose } from '@gsm-app/hooks/useModalOnClose';
import { useNgpConfig } from '@gsm-app/hooks/useNgpConfig';
import { useTestExecutionCreate } from '@gsm-app/hooks/useTestExecutionCreate';
import type { TestExecution } from '@gsm-app/hooks/useTestExecutions';
import { useEnvVariables } from '@gsm-app/providers/EnvVariablesProvider';
import { useGameChannels } from '@gsm-app/routes/Play/hooks/useGameChannels';
import { isValidUUID } from '@gsm-app/utils/uuid';
import { createError } from '@gsm-common/utils/toast/createError';
import { createSuccess } from '@gsm-common/utils/toast/createSuccess';
import { IconCopyPlus, IconRefresh } from '@hawkins/assets';
import IconCircleI from '@hawkins/assets/lib/icons/iconCircleI';
import {
    Button,
    ButtonGroup,
    ContextualBanner,
    Divider,
    Dropdown,
    type DropdownOption,
    Heading,
    Input,
    Modal,
    ModalBody,
    ModalFooter,
    ModalHeader,
    type ModalProps,
    Slider,
    Stack,
    Tab,
    TabList,
    TabPanel,
    TabPanelItem,
    TabbedInterface,
    Text,
    ToggleButton,
    ToggleButtonGroup,
    Tooltip,
} from '@hawkins/components';

import { useFullStory } from '@gsm-app/hooks/useFullStory';

import { Colors, Dimensions, Typography } from '@hawkins/variables';
import { yupResolver } from '@hookform/resolvers/yup';
import { EnvVarTable, EnvVarTableHeaderActions } from '@ncgt/common-ui';
import type { EnvVar } from '@ncgt/common/models/envVar';
import { useQueryClient } from '@tanstack/react-query';
import moment from 'moment-timezone';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { Controller, FormProvider, useFieldArray, useForm } from 'react-hook-form';
import * as yup from 'yup';

interface VideoSettings {
    resolution?: number;
    fps?: number;
}

interface NewTestModalProps extends ModalProps {
    onClose: () => void;
    gameId: string;
    gameName: string;
}

interface BuildSearchError {
    title: string;
    detail?: string;
}

const DISALLOWED_ENV_VAR_KEYS = ['NFLX_AUTOPLAY_MODE', 'NFLX_AUTOPLAY_SEED'];

export enum TEST_SUITE {
    BOTH = 'both',
    OCGAPERF = 'ocgaperf',
    SINGLE_SESSION = 'single_session',
}

const createEmptyEnvVar = (): EnvVar => ({ key: '', value: '', enabled: true });

const normalizeEnabled = (vars: EnvVar[]): EnvVar[] =>
    vars.map((v) => ({ key: v.key, value: v.value, enabled: v.enabled !== false }));

const envVarSchema = yup.object({
    vars: yup
        .array(
            yup.object({
                key: yup
                    .string()
                    .required('Key is required')
                    .notOneOf(DISALLOWED_ENV_VAR_KEYS, 'This variable is not configurable.'),
                value: yup.string().required('Value is required'),
                enabled: yup.boolean().optional(),
            }),
        )
        .test('no-duplicate-keys', function (vars) {
            if (!vars) return true;
            const seen = new Set<string>();
            const errors: yup.ValidationError[] = [];
            vars.forEach((v, i) => {
                if (!v?.key) return;
                if (seen.has(v.key)) {
                    errors.push(
                        this.createError({
                            path: `vars[${i}].key`,
                            message: 'Duplicate key',
                        }),
                    );
                } else {
                    seen.add(v.key);
                }
            });
            return errors.length === 0 ? true : new yup.ValidationError(errors);
        })
        .required(),
});

// Validation schema for Settings tab
const testSettingsSchema = yup.object({
    selectedBuild: yup.string().required('Build selection is required'),
    resolution: yup.number().oneOf([720, 1080]).required(),
    fps: yup.number().oneOf([30, 60]).required(),
    duration: yup.number().min(MIN_TEST_DURATION).max(MAX_TEST_DURATION).required(),
    ocgaUuid: yup
        .string()
        .optional()
        .test('is-valid-uuid', 'Invalid UUID format', (value) => !value || isValidUUID(value)),
    testSuite: yup.string().oneOf([TEST_SUITE.BOTH, TEST_SUITE.OCGAPERF, TEST_SUITE.SINGLE_SESSION]).required(),
    durationInput: yup
        .string()
        .test('is-valid-mmss', 'Invalid format. Use MM:SS (e.g., 5:30)', (value) => {
            if (!value?.trim()) return false;
            const match = value.match(/^(\d{1,2}):(\d{2})$/);
            if (!match) return false;
            const seconds = Number.parseInt(match[2], 10);
            return seconds < 60;
        })
        .required(),
});

export const NewTestModal = ({ open, onClose, gameId, gameName }: NewTestModalProps) => {
    const ngpConfig = useNgpConfig(gameId);

    const [override, setOverride] = useState<TestExecution>();
    const { gameOptions, channelOptions, activeBuild, selectedGame, selectedChannel, setSelectedGame } =
        useGameChannels();
    const [loading, setLoading] = useState(false);
    const { mutateAsync: createTestExecutionAsync } = useTestExecutionCreate();
    const [displayName, setDisplayName] = useState<string | undefined>();
    const { trackEvent } = useFullStory();
    const { getEnvVariablesForGame } = useEnvVariables();
    const { testExecutionOcgaUuid, resourceEnvelope } = useFeature(gameId ? Number(gameId) : undefined);
    const isEnvelopeGame = resourceEnvelope != null;

    const envVarMethods = useForm<{ vars: EnvVar[] }>({
        mode: 'onChange',
        reValidateMode: 'onChange',
        resolver: yupResolver(envVarSchema) as never,
        defaultValues: { vars: [] },
    });
    const {
        fields: envVarFields,
        append: appendEnvVar,
        remove: removeEnvVar,
        update: updateEnvVarField,
    } = useFieldArray({ control: envVarMethods.control, name: 'vars' });
    const envVarErrorsState = envVarMethods.formState.errors;

    // Get default values for form
    const getDefaultValues = useCallback(() => {
        // Use system defaults directly since NGP config is disabled
        const ngpResolution = ngpConfig.data?.resolution || DEFAULT_TEST_RESOLUTION;
        const ngpFps = ngpConfig.data?.fps || DEFAULT_TEST_FPS;

        return {
            selectedBuild: '',
            resolution: ngpResolution,
            fps: ngpFps,
            duration: DEFAULT_TEST_DURATION,
            ocgaUuid: '',
            testSuite: isEnvelopeGame ? TEST_SUITE.SINGLE_SESSION : TEST_SUITE.BOTH,
            durationInput: moment.utc(DEFAULT_TEST_DURATION * 1000).format('m:ss'),
        };
    }, [ngpConfig.data, isEnvelopeGame]);

    // Initialize react-hook-form for Settings tab
    const {
        control,
        handleSubmit,
        reset,
        formState: { errors },
        watch,
        setValue,
    } = useForm({
        resolver: yupResolver(testSettingsSchema),
        defaultValues: getDefaultValues(),
        mode: 'onChange',
    });

    // Watch form values
    const duration = watch('duration');
    const durationInput = watch('durationInput');
    const resolution = watch('resolution');
    const ocgaUuid = watch('ocgaUuid');
    const testSuite = watch('testSuite');
    const fps = watch('fps');
    const selectedBuildValue = watch('selectedBuild');

    // Helper functions for duration formatting and parsing
    const formatSecondsToMMSS = useCallback((seconds: number): string => {
        return moment.utc(seconds * 1000).format('m:ss');
    }, []);

    const applyDefaults = useCallback(() => {
        // Use system defaults directly since NGP config is disabled
        const ngpResolution = ngpConfig.data?.resolution || DEFAULT_TEST_RESOLUTION;
        const ngpFps = ngpConfig.data?.fps || DEFAULT_TEST_FPS;

        setValue('resolution', ngpResolution);
        setValue('fps', ngpFps);
        setValue('ocgaUuid', '');
        setValue('duration', DEFAULT_TEST_DURATION);
        setValue('durationInput', formatSecondsToMMSS(DEFAULT_TEST_DURATION));
    }, [formatSecondsToMMSS, setValue, ngpConfig.data]);

    // Apply defaults when modal opens
    useEffect(() => {
        if (open && gameId) {
            reset(getDefaultValues());
        }
    }, [open, gameId, reset, getDefaultValues]);

    const handleCopyPlaySessionVars = useCallback(() => {
        if (!selectedGame?.value) return;
        const playSessionVars = getEnvVariablesForGame(selectedGame.value).filter((v) => v.enabled !== false);
        const merged = new Map<string, EnvVar>();
        for (const existing of envVarMethods.getValues('vars')) {
            if (existing.key) merged.set(existing.key, existing);
        }
        for (const incoming of playSessionVars) {
            merged.set(incoming.key, { key: incoming.key, value: String(incoming.value), enabled: true });
        }
        envVarMethods.reset({ vars: normalizeEnabled(Array.from(merged.values())) });
    }, [selectedGame, getEnvVariablesForGame, envVarMethods]);

    useEffect(() => {
        setDisplayName(displayName ? displayName : (activeBuild?.label ?? selectedChannel?.subtitle));
    }, [displayName, selectedChannel, activeBuild]);

    const parseMMSSToSeconds = useCallback((input: string): number | null => {
        const trimmed = input.trim();
        if (!trimmed) return null;

        // Match MM:SS format
        const match = trimmed.match(/^(\d{1,2}):(\d{2})$/);
        if (!match) return null;

        const minutes = Number.parseInt(match[1], 10);
        const seconds = Number.parseInt(match[2], 10);

        if (seconds >= 60) return null; // Invalid seconds

        return moment.duration({ minutes, seconds }).asSeconds();
    }, []);

    // Sync slider changes to duration input
    const handleSliderChange = useCallback(
        (event: React.SyntheticEvent<HTMLInputElement>, value: number | number[]) => {
            const newDuration = value as number;
            setValue('duration', newDuration);
            setValue('durationInput', formatSecondsToMMSS(newDuration));
        },
        [formatSecondsToMMSS, setValue],
    );

    // Sync duration input changes to slider
    const handleDurationInputChange = useCallback(
        (event: React.ChangeEvent<HTMLInputElement>) => {
            const inputValue = event.target.value;
            setValue('durationInput', inputValue);

            // Update duration if valid
            const seconds = parseMMSSToSeconds(inputValue);
            if (seconds !== null && seconds >= MIN_TEST_DURATION && seconds <= MAX_TEST_DURATION) {
                setValue('duration', seconds);
            }
        },
        [parseMMSSToSeconds, setValue],
    );

    // Helper function to format duration for display
    const formatDuration = useCallback((seconds: number): string => {
        const duration = moment.duration(seconds, 'seconds');
        const minutes = Math.floor(duration.asMinutes());
        const remainingSeconds = duration.seconds();

        if (minutes > 0) {
            return `${minutes}:${remainingSeconds.toString().padStart(2, '0')}`;
        }
        return `${seconds}s`;
    }, []);

    // Explicity calculate our slider mark to avoid the defalt mark per step increase
    const sliderMarks = useMemo(() => {
        const numMarks = 11;
        const step = (MAX_TEST_DURATION - MIN_TEST_DURATION) / (numMarks - 1);

        return Array.from({ length: numMarks }, (_, i) => ({
            value: Math.round(MIN_TEST_DURATION + step * i),
        }));
    }, []);

    const { data, isLoading } = useBuildSearch(gameId, displayName);

    const buildDropdownOptions = useMemo<DropdownOption<string>[]>(() => {
        const builds = data?.data ? data?.data : [];
        return builds.map((buildSearch) => {
            return {
                label: buildSearch.build.displayName,
                value: buildSearch.build.buildId,
                subtitle: buildSearch.channels?.join(', '),
            };
        });
    }, [data]);

    useEffect(() => {
        // Try to find an option to populate the selected build
        const builds = data?.data ? data?.data : [];
        if (!selectedBuildValue && activeBuild) {
            builds.forEach((build) => {
                if (build.build.displayName === `${activeBuild.label} (${activeBuild.id})`) {
                    setValue('selectedBuild', build.build.buildId);
                }
            });
        }
    }, [activeBuild, selectedBuildValue, data?.data, setValue]);

    const onBuildSearchInputChanged = useCallback((searchTerm: string) => {
        setDisplayName(searchTerm);
    }, []);

    const onFilterOptions = useCallback(
        (searchTerm: string) => {
            return buildDropdownOptions.filter((option: DropdownOption<string>) => {
                return option.label.includes(searchTerm);
            });
        },
        [buildDropdownOptions],
    );

    const queryClient = useQueryClient();

    const onQueueTest = handleSubmit(async (formData) => {
        if (gameId && formData.selectedBuild) {
            const isEnvVarsValid = await envVarMethods.trigger();
            if (!isEnvVarsValid) return;
            const envVarsPayload = envVarMethods
                .getValues('vars')
                .filter((v) => v.enabled !== false && v.key && v.value)
                .map(({ key, value }) => ({ key, value }));
            if (selectedGame?.value) {
                trackEvent('New Test Execution', {
                    game: gameId,
                    build: formData.selectedBuild,
                    environmentVariables: envVarsPayload.length,
                });

                // Extract buildId from the selected build
                const selectedBuildData = buildDropdownOptions.find((opt) => opt.value === formData.selectedBuild);
                const buildIdMatch = selectedBuildData?.label.match(/\(([^)]+)\)/);

                try {
                    setLoading(true);
                    const result = await createTestExecutionAsync({
                        gameId: gameId,
                        buildId: buildIdMatch![1],
                        override: Boolean(override),
                        fps: formData.fps,
                        resolution: formData.resolution,
                        ocgaUuid: formData.ocgaUuid,
                        autoplayDuration: formData.duration,
                        testSuite: formData.testSuite === TEST_SUITE.BOTH ? undefined : formData.testSuite,
                        envVars: envVarsPayload,
                    });
                    if (result.data?.testExecution) {
                        setOverride(result.data.testExecution);
                    } else {
                        createSuccess({
                            title: 'Test Launched Successfully',
                        });
                        onClose();
                        setOverride(undefined);
                    }
                } catch (error: unknown) {
                    const errorMessage = error instanceof Error ? error.message : 'Unknown error occurred';
                    createError({
                        title: 'Error Launching Test',
                        body: errorMessage,
                        options: {
                            id: 'test-queue-error',
                        },
                    });
                    onClose();
                    setOverride(undefined);
                } finally {
                    setLoading(false);
                }
                queryClient.invalidateQueries({ queryKey: ['testExecutions'] });
            } else {
                onClose();
                setOverride(undefined);
            }
        }
    });

    const selectedBuildOption = useMemo(() => {
        return buildDropdownOptions.find((opt) => opt.value === selectedBuildValue);
    }, [buildDropdownOptions, selectedBuildValue]);

    const handleCancel = async () => {
        setLoading(false);
        setDisplayName(undefined);
        reset(getDefaultValues());
        envVarMethods.reset({ vars: [] });
        onClose();
        setOverride(undefined);
    };

    const handleOnClose = useModalOnClose({ onClose });

    const hasEnvVarErrors = Boolean(envVarErrorsState.vars);

    return (
        <>
            <Modal open={open} style={{ width: 600 }} maxWidth='medium' onClose={handleOnClose}>
                <ModalHeader>
                    <Heading level={0}>New Test Execution for {gameName}</Heading>
                </ModalHeader>
                <ModalBody>
                    <Stack gap={Dimensions.Space8}>
                        {override && (
                            <ContextualBanner
                                variant='warning'
                                text={`Test Execution with state "${override?.state}" found. Are you sure you'd like to queue a new test?`}
                            />
                        )}

                        {ocgaUuid && isValidUUID(ocgaUuid) && (
                            <ContextualBanner
                                variant='warning'
                                text={`OCGA UUID "${ocgaUuid}" Selected. ${testSuite === TEST_SUITE.BOTH ? 'Both Load Test and Single Session' : testSuite === TEST_SUITE.OCGAPERF ? 'Only Load Test' : 'Only Single Session Test'} will run.`}
                            />
                        )}

                        {/* Custom label with tooltip */}
                        <Stack orientation='horizontal' gap={Dimensions.Space4} style={{ alignItems: 'center' }}>
                            <Text bold>Build</Text>
                            <Text color={Colors.Red400} bold>
                                *
                            </Text>{' '}
                            {/* Required star */}
                            <Tooltip label='Specify the build to be tested from all uploaded builds.'>
                                <IconCircleI size='small' color={Colors.Indigo400} tabIndex={-1} />
                            </Tooltip>
                        </Stack>

                        {/* Build */}
                        <Controller
                            name='selectedBuild'
                            control={control}
                            render={({ field }) => (
                                <Dropdown
                                    placeholder='Search build'
                                    loading={isLoading}
                                    onSearchInputChange={onBuildSearchInputChanged}
                                    clearSearchOnSelect={false}
                                    debounceTime={250}
                                    value={selectedBuildOption}
                                    onChange={(selected: DropdownOption<string> | null) => {
                                        if (selected) {
                                            field.onChange(selected.value);
                                        }
                                    }}
                                    options={buildDropdownOptions}
                                    searchable={true}
                                    filterOptions={onFilterOptions}
                                    disabled={loading}
                                />
                            )}
                        />

                        <TabbedInterface>
                            <TabList indicatorColor='monochrome'>
                                <Tab value='settings'>Session Settings</Tab>
                                <Tab value='envvars' badge={hasEnvVarErrors}>
                                    Environment Variables
                                </Tab>
                                {testExecutionOcgaUuid && <Tab value='suite'>Test Suites</Tab>}
                            </TabList>
                            <Divider style={{ marginBlock: '0' }} />
                            <TabPanel style={{ paddingTop: Dimensions.Space16 }}>
                                <TabPanelItem value='settings'>
                                    <Stack gap={Dimensions.RawSpace8}>
                                        {/* Video Settings - FPS & Resolution */}
                                        <Stack
                                            gap={Dimensions.Space8}
                                            orientation='horizontal'
                                            style={{
                                                width: '100%',
                                                display: 'grid',
                                                gridTemplateColumns: '1fr 1fr',
                                                marginTop: Dimensions.Space4,
                                            }}
                                        >
                                            <Controller
                                                name='resolution'
                                                control={control}
                                                render={({ field }) => (
                                                    <Dropdown
                                                        label='Resolution'
                                                        value={VIDEO_RESOLUTION_OPTIONS.find(
                                                            (option) => option.value === field.value,
                                                        )}
                                                        options={VIDEO_RESOLUTION_OPTIONS}
                                                        onChange={(selectedOption: DropdownOption<number> | null) => {
                                                            field.onChange(selectedOption?.value);
                                                        }}
                                                        disabled={loading}
                                                    />
                                                )}
                                            />
                                            <Controller
                                                name='fps'
                                                control={control}
                                                render={({ field }) => (
                                                    <Dropdown
                                                        label='Frame Rate'
                                                        value={TEST_FPS_OPTIONS.find(
                                                            (option) => option.value === field.value,
                                                        )}
                                                        options={TEST_FPS_OPTIONS}
                                                        onChange={(selectedOption: DropdownOption<number> | null) => {
                                                            field.onChange(selectedOption?.value);
                                                        }}
                                                        disabled={loading}
                                                    />
                                                )}
                                            />
                                        </Stack>
                                        {/* Test Duration Slider */}
                                        <Stack gap={Dimensions.Space8} style={{ marginTop: Dimensions.Space4 }}>
                                            <Text bold>Single Session Autoplay Duration</Text>
                                            <div
                                                style={{
                                                    display: 'flex',
                                                    gap: `${Dimensions.RawSpace8}px`,
                                                    alignItems: 'flex-start',
                                                    width: '100%',
                                                }}
                                            >
                                                <div style={{ flexShrink: 0 }}>
                                                    <div style={{ position: 'relative', width: '120px' }}>
                                                        <Controller
                                                            name='durationInput'
                                                            control={control}
                                                            render={({ field }) => (
                                                                <Input
                                                                    label=''
                                                                    placeholder='MM:SS'
                                                                    value={field.value}
                                                                    onChange={(
                                                                        e: React.ChangeEvent<HTMLInputElement>,
                                                                    ) => {
                                                                        field.onChange(e);
                                                                        handleDurationInputChange(e);
                                                                    }}
                                                                    validationStatus={
                                                                        errors.durationInput ? 'error' : undefined
                                                                    }
                                                                    disabled={loading}
                                                                    validationMessage='' // Disable built-in message to prevent expansion
                                                                    style={{
                                                                        paddingRight: `${Dimensions.RawSpace40}px`,
                                                                    }}
                                                                />
                                                            )}
                                                        />
                                                        <Text
                                                            variant='body'
                                                            colorVariant='faded'
                                                            style={{
                                                                position: 'absolute',
                                                                right: Dimensions.Space12,
                                                                top: '50%',
                                                                transform: 'translateY(-50%)',
                                                                pointerEvents: 'none',
                                                            }}
                                                        >
                                                            mins
                                                        </Text>
                                                    </div>
                                                    <div
                                                        style={{
                                                            height: `${Dimensions.RawSpace20}px`,
                                                            marginTop: Dimensions.Space4,
                                                            fontSize: Typography.FontSize12,
                                                            color: Colors.Red400,
                                                        }}
                                                    >
                                                        {errors.durationInput?.message && (
                                                            <span>{errors.durationInput.message}</span>
                                                        )}
                                                    </div>
                                                </div>
                                                <div style={{ flex: 1, minWidth: 0, position: 'relative' }}>
                                                    <Slider
                                                        min={MIN_TEST_DURATION}
                                                        max={MAX_TEST_DURATION}
                                                        step={TEST_DURATION_STEP}
                                                        value={duration}
                                                        onChange={handleSliderChange}
                                                        marks={sliderMarks}
                                                        style={{ width: '100%' }}
                                                        translate={{
                                                            'slider.value.label': ({ value }) =>
                                                                formatDuration(value as number),
                                                        }}
                                                        disabled={loading}
                                                    />
                                                    {/* Fixed position labels that stay with slider ends */}
                                                    <div
                                                        style={{
                                                            position: 'absolute',
                                                            top: '100%',
                                                            left: 0,
                                                            marginTop: Dimensions.Space4,
                                                            pointerEvents: 'none',
                                                        }}
                                                    >
                                                        <Text variant='body' colorVariant='faded'>
                                                            0:15
                                                        </Text>
                                                    </div>
                                                    <div
                                                        style={{
                                                            position: 'absolute',
                                                            top: '100%',
                                                            right: 0,
                                                            marginTop: Dimensions.Space4,
                                                            pointerEvents: 'none',
                                                        }}
                                                    >
                                                        <Text variant='body' colorVariant='faded'>
                                                            30:00
                                                        </Text>
                                                    </div>
                                                </div>
                                            </div>
                                        </Stack>
                                    </Stack>

                                    {/* Reset to Default Button */}
                                    <div style={{ display: 'flex', justifyContent: 'flex-start' }}>
                                        <Button
                                            icon={IconRefresh}
                                            onClick={applyDefaults}
                                            disabled={loading}
                                            variant='tertiary'
                                            compact={true}
                                            style={{
                                                gap: `${Dimensions.RawSpace6}px`,
                                                fontSize: Typography.FontSize12,
                                            }}
                                        >
                                            Reset to Default
                                        </Button>
                                    </div>
                                </TabPanelItem>
                                <TabPanelItem value='envvars'>
                                    <Stack gap={Dimensions.RawSpace8}>
                                        <Stack
                                            orientation='horizontal'
                                            gap={Dimensions.RawSpace8}
                                            alignItems='center'
                                            style={{ display: 'flex' }}
                                        >
                                            <Tooltip
                                                label='Copy environment variables from your most recent play session for this game.'
                                                placement='top'
                                            >
                                                <Button
                                                    variant='tertiary'
                                                    icon={IconCopyPlus}
                                                    onClick={handleCopyPlaySessionVars}
                                                    style={{ height: Dimensions.RawSpace32, marginLeft: 'auto' }}
                                                    disabled={!selectedGame?.value || loading}
                                                >
                                                    Use Play Session Settings
                                                </Button>
                                            </Tooltip>
                                            <EnvVarTableHeaderActions
                                                disabled={loading}
                                                onImport={(vars) =>
                                                    envVarMethods.reset({
                                                        vars: vars.length > 0 ? normalizeEnabled(vars) : [],
                                                    })
                                                }
                                                getExportData={() => normalizeEnabled(envVarMethods.getValues('vars'))}
                                            />
                                        </Stack>
                                        <FormProvider {...envVarMethods}>
                                            <EnvVarTable
                                                fields={envVarFields}
                                                disabled={loading}
                                                onAdd={() => appendEnvVar(createEmptyEnvVar())}
                                                onRemove={(index) => removeEnvVar(index)}
                                                onToggleEnabled={(index, isEnabled) => {
                                                    const current = envVarMethods.getValues(`vars.${index}`);
                                                    updateEnvVarField(index, { ...current, enabled: !isEnabled });
                                                }}
                                            />
                                        </FormProvider>
                                    </Stack>
                                </TabPanelItem>
                                {testExecutionOcgaUuid ? (
                                    <TabPanelItem value='suite'>
                                        <Stack gap={Dimensions.Space24}>
                                            {/* OCGA UUID Override */}
                                            <Controller
                                                name='ocgaUuid'
                                                control={control}
                                                render={({ field }) => (
                                                    <Input
                                                        label='OCGA UUID'
                                                        value={field.value}
                                                        onChange={(value) => field.onChange(value)}
                                                        disabled={loading}
                                                        validationStatus={errors.ocgaUuid ? 'error' : undefined}
                                                    />
                                                )}
                                            />
                                            <Stack gap={Dimensions.Space4}>
                                                <Text colorVariant='faded'>Select which test suite(s) to run</Text>
                                                <Controller name='testSuite' control={control} render={({ field }) => (
                                                    <ToggleButtonGroup value={field.value} onChange={(ev, newTestSuiteValue) => {
                                                        field.onChange(newTestSuiteValue);
                                                    }}>
                                                        <ToggleButton value={TEST_SUITE.BOTH}>Both</ToggleButton>
                                                        <ToggleButton value={TEST_SUITE.OCGAPERF}>Load Test</ToggleButton>
                                                        <ToggleButton value={TEST_SUITE.SINGLE_SESSION}>Single Session</ToggleButton>
                                                    </ToggleButtonGroup>
                                                )} />
                                            </Stack>
                                        </Stack>
                                    </TabPanelItem>
                                ) : (
                                    <></>
                                )}
                            </TabPanel>
                        </TabbedInterface>
                    </Stack>
                </ModalBody>
                <ModalFooter>
                    <ButtonGroup justifyContent='flex-end'>
                        <Button variant='secondary' onClick={handleCancel}>
                            Cancel
                        </Button>
                        <Button
                            onClick={onQueueTest}
                            disabled={!selectedBuildValue || loading || Object.keys(errors).length > 0}
                        >
                            {override ? 'Launch Anyway' : 'Queue'}
                        </Button>
                    </ButtonGroup>
                </ModalFooter>
            </Modal>
        </>
    );
};
