import {
    Button,
    ButtonGroup,
    Heading,
    Modal,
    ModalBody,
    ModalFooter,
    ModalHeader,
    type ModalProps,
} from '@hawkins/components';
import { plural } from '@gsm-common/utils/string/plural';
import type { TestExecution } from '@gsm-app/hooks/useTestExecutions';


interface DeleteTestModalProps extends ModalProps {
    onClose: () => void;
    selectedIds: TestExecution[];
    onDelete: () => void;
}

export const DeleteTestModal = ({ open, onClose, onDelete, selectedIds = [] }: DeleteTestModalProps) => {
    return (
        <>
            <Modal open={open} style={{ width: 600 }} maxWidth='medium' >
                <ModalHeader>
                    <Heading level={0}>{`Delete ${selectedIds.length} Test ${plural('Execution', selectedIds.length)}?`}</Heading>
                </ModalHeader>
                <ModalBody>
                    Please confirm you'd like to delete the selected test executions
                </ModalBody>
                <ModalFooter>
                    <ButtonGroup justifyContent='flex-end'>
                        <Button variant='secondary' onClick={onClose}>
                            Cancel
                        </Button>
                        <Button onClick={onDelete}>
                            Delete
                        </Button>
                    </ButtonGroup>
                </ModalFooter>
            </Modal>
        </>
    );
};
