import type { TEST_SUITE } from '@gsm-app/components/NewTestModal';
import { useMutation, useQueryClient } from '@tanstack/react-query';

async function enqueueTestExecution({
    gameId,
    buildId,
    override,
    fps,
    resolution,
    ocgaUuid,
    autoplayDuration,
    testSuite,
    envVars,
}: {
    gameId: string;
    buildId: string;
    override: boolean;
    fps?: number;
    resolution?: number;
    ocgaUuid?: string;
    autoplayDuration?: number;
    testSuite?: TEST_SUITE;
    envVars: { key: string; value: string }[];
}): Promise<any> {
    const response = await fetch(`api/games/${gameId}/tests`, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
        },
        body: JSON.stringify({
            buildId,
            override,
            fps,
            resolution,
            ocgaUuid,
            autoplayDuration,
            testSuite,
            envVars,
        }),
    });

    if (!response.ok) {
        let errorData: any;
        try {
            errorData = await response.text();
            errorData = JSON.parse(errorData); // Text only if it fails
        } catch (_error) {}
        throw new Error(errorData.message ? errorData.message : errorData);
    }
    return response.json();
}

export function useTestExecutionCreate() {
    const queryClient = useQueryClient();
    return useMutation({
        mutationFn: enqueueTestExecution,
        onMutate: () => {
            queryClient.invalidateQueries({ queryKey: ['testExecutions'] });
        },
    });
}
