import { NewTestModal } from '@gsm-app/components/NewTestModal';
import { DeleteTestModal } from '@gsm-app/components/DeleteTestModal';
import { useFeature } from '@gsm-app/hooks/useFeature';
import {
    TEST_EXECUTIONS_KEY,
    type TestExecution,
    TestSuite,
    useTestExecutions,
} from '@gsm-app/hooks/useTestExecutions';
import { Content } from '@gsm-common/components/Content';
import { Layout } from '@gsm-common/components/Layout';
import { paramsObject, useSearchParams } from '@gsm-common/hooks/useSearchParams';
import { keyFromOptions } from '@gsm-common/utils/dropdown/keyFromOptions';
import { IconDocumentChart, IconUser, IconWarning } from '@hawkins/assets';
import {
    Badge,
    Button,
    Dropdown,
    getFuzzyFilterOption,
    Heading,
    Paper,
    Stack,
    Tag,
    Tooltip,
} from '@hawkins/components';
import { Dimensions } from '@hawkins/variables';
import { useQueryClient } from '@tanstack/react-query';
import { forwardRef, useCallback, useMemo, useRef, useState } from 'react';
import { DropdownTrigger } from '../Play/components/PageHeader/components/DropdownTrigger';
import { useGameChannels } from '../Play/hooks/useGameChannels';
import styles from './TestExecutionsTable.module.css';
import { useIdentity } from '@gsm-app/providers/IdentityProvider';
import { Role } from '@ncgt/common/models/identity';
import { DEFAULT_TEST_FPS, DEFAULT_TEST_RESOLUTION } from '@gsm-app/constants';

import {
    AllCommunityModule,
    type IRowNode,
    type RowSelectedEvent,
    type RowSelectionOptions,
    type ColDef,
    type ColGroupDef,
    type ICellRendererParams,
} from 'ag-grid-community';
import {
    ColumnsToolPanelModule,
    FiltersToolPanelModule,
    MenuModule,
    SetFilterModule,
    SideBarModule,
} from 'ag-grid-enterprise';
import { type AgGridReact, TableNext } from '@hawkins/table-next';
import { plural } from '@gsm-common/utils/string/plural';

const PAGINATION_PAGE_SIZE = 25;
const PAGINATION_OPTIONS = [25, 50, 100];

type SearchParams = { gameId?: string; channelName?: string; startDate?: string; endDate?: string };

function convertMilliseconds(milliseconds: number) {
    const msPerMinute = 60 * 1000;
    const msPerHour = msPerMinute * 60;

    const hours = Math.floor(milliseconds / msPerHour);
    const minutes = Math.floor((milliseconds % msPerHour) / msPerMinute);
    const seconds = Math.floor((milliseconds % msPerMinute) / 1000);

    if (hours > 0) {
        return `${hours}h ${minutes}m ${seconds}s`;
    } else if (minutes > 0) {
        return `${minutes}m ${seconds}s`;
    } else {
        return `${seconds}s`;
    }
}

function convertSecondsToDisplay(seconds: number) {
    const minutes = Math.floor(seconds / 60);
    const remainingSeconds = seconds % 60;

    if (minutes > 0) {
        return `${minutes}:${remainingSeconds.toString().padStart(2, '0')}`;
    } else {
        return `${seconds}s`;
    }
}

export const TestExecutionsTable = () => {
    const [{ gameId }, setParams] = useSearchParams<SearchParams>();
    const { identity } = useIdentity();
    const queryClient = useQueryClient();
    const { data: testExecutions = [], error, isLoading, isRefetching, isFetching } = useTestExecutions(gameId);
    const [modalOpen, setModalOpen] = useState(false);
    const [deleteModalOpen, setDeleteModalOpen] = useState(false);
    const { gameOptions, selectedGame } = useGameChannels();
    const { resourceEnvelope } = useFeature(gameId ? Number(gameId) : undefined);

    const onNewTest = useCallback(() => {
        if (selectedGame) {
            setModalOpen(true);
        }
    }, [selectedGame]);

    const [selectedTests, setSelectedTests] = useState<TestExecution[]>([]);
    const [deleteExecuting, setDeleteExecuting] = useState(false);
    const gridRef = useRef<AgGridReact<TestExecution>>(null);

    const isNCGTAdmin = identity.roles.has(Role.NCGT_ADMIN);

    // Hide load test rows from non-admin users for envelope games
    const filteredTestExecutions = useMemo(() => {
        if (isNCGTAdmin || !resourceEnvelope) return testExecutions;
        return testExecutions.filter(
            (t) => !!t.metadata?.ssRunId || t.testSuite === TestSuite.SINGLE_SESSION,
        );
    }, [testExecutions, isNCGTAdmin, resourceEnvelope]);

    const modules = useMemo(
        () => [
            AllCommunityModule,
            SetFilterModule,
            MenuModule,
            SideBarModule,
            ColumnsToolPanelModule,
            FiltersToolPanelModule,
        ],
        [],
    );

    const rowSelection = useMemo<RowSelectionOptions<TestExecution>>(() => {
        return { mode: 'multiRow' };
    }, []);

    const defaultColDef = useMemo<ColDef>(() => {
        return {
            editable: false,
            filter: true,
            floatingFilter: true,
            minWidth: 100,
            resizable: true,
            sortable: true,
            suppressHeaderMenuButton: true,
            suppressHeaderContextMenu: true,
            wrapHeaderText: true,
            autoHeaderHeight: true,
        };
    }, []);

    const autoGroupColumnDef = useMemo<ColDef>(() => {
        return {
            cellRendererParams: {
                checkbox: false,
                suppressCount: false,
            },
            headerName: 'Group',
            menuTabs: [],
            minWidth: 250,
        };
    }, []);

    const columnDefs = useMemo<(ColDef<TestExecution> | ColGroupDef<TestExecution>)[]>(() => {
        return [
            {
                field: 'createdDate',
                headerName: 'Time',
                width: 155,
                maxWidth: 155,
                filter: 'agDateColumnFilter',
                cellRenderer: (params: ICellRendererParams<TestExecution, number>) => {
                    if (!params.value) {
                        return null;
                    }
                    const date = new Date(params.value);
                    return (
                        <Stack
                            gap={Dimensions.Space8}
                            orientation='horizontal'
                            layout={{
                                alignItems: 'center',
                                justifyContent: 'space-between',
                            }}
                        >
                            {date.toLocaleDateString(undefined, {
                                year: '2-digit',
                                month: '2-digit',
                                day: '2-digit',
                                hour: '2-digit',
                                minute: '2-digit',
                            })}
                        </Stack>
                    );
                },
            },
            {
                field: 'createdBy',
                headerName: 'User',
                sortable: false,
                filter: 'agSetColumnFilter',
                width: 75,
                maxWidth: 75,
                cellRenderer: (params: ICellRendererParams<TestExecution, string>) => {
                    if (!params.value) return null;
                    return (
                        <Tooltip label={params.value}>
                            <IconUser size='small' />
                        </Tooltip>
                    );
                },
            },
            {
                field: 'buildId',
                headerName: 'Build Id',
                width: 160,
                maxWidth: 160,
                filter: 'agTextColumnFilter',
            },
            {
                field: 'buildLabel',
                headerName: 'Label',
                filter: 'agTextColumnFilter',
            },
            {
                field: 'testSuite',
                headerName: 'Type',
                sortable: false,
                width: 130,
                maxWidth: 130,
                filter: 'agSetColumnFilter',
                valueGetter: (params: { data?: TestExecution }) => {
                    if (params.data?.metadata?.ssRunId || params.data?.testSuite === TestSuite.SINGLE_SESSION) {
                        return 'Single Session';
                    }
                    return 'Load Test';
                },
                cellStyle: {
                    display: 'flex',
                    alignItems: 'center',
                },
                cellRenderer: (params: ICellRendererParams<TestExecution, string>) => {
                    const isLoadTest = params.value === 'Load Test';
                    return (
                        <Stack orientation='horizontal' gap={Dimensions.Space4} style={{ alignItems: 'center' }}>
                            <Tag variant='compact' color='gray'>
                                {params.value}
                            </Tag>
                            {isLoadTest && resourceEnvelope && (
                                <Tag variant='compact' color='blue'>
                                    Admin
                                </Tag>
                            )}
                        </Stack>
                    );
                },
            },
            {
                field: 'state',
                headerName: 'State',
                cellRenderer: (params: ICellRendererParams<TestExecution, string>) => {
                    let color = 'UNKNOWN';
                    let displayValue = params.value;
                    switch (params.value) {
                        case 'PENDING':
                            color = 'NEW';
                            break;
                        case 'ERROR':
                            color = 'FAILURE';
                            break;
                        case 'FAILED':
                            color = 'FAILURE';
                            break;
                        case 'ABORTED':
                            color = 'FAILURE';
                            break;
                        case 'RUNNING':
                            color = 'IN_PROGRESS';
                            break;
                        case 'SUCCEEDED':
                            color = 'COMPLETE';
                            displayValue = 'COMPLETED';
                            break;
                        case 'QUEUED':
                            color = 'UNKNOWN';
                            break;
                        default:
                            color = 'UNKNOWN';
                            break;
                    }
                    return (
                        <Badge color={color} compact>
                            {displayValue}
                        </Badge>
                    );
                },
                width: 145,
                maxWidth: 145,
            },
            {
                field: 'metadata',
                headerName: 'Result',
                filter: 'agNumberColumnFilter',
                sortable: false,
                cellRenderer: (params: ICellRendererParams<TestExecution, string>) => {
                    const instanceCount = params.data?.metadata?.instanceCount;
                    const ssResult = params.data?.metadata?.ssOverallResult;
                    const isSingleSession = !!params.data?.metadata?.ssRunId;
                    return (
                        <Stack orientation='horizontal' gap={Dimensions.Space12} style={{ alignItems: 'center' }}>
                            <Tooltip label={isSingleSession ? 'Predicted Instance Count' : 'Instance Count'}>
                                <span>{instanceCount}</span>
                            </Tooltip>
                            {ssResult === 'PASSED' && <Tooltip label='Overall Test Result'><Tag variant='compact' color='green'>Passed</Tag></Tooltip>}
                            {ssResult === 'FAILED' && <Tooltip label='Overall Test Result'><Tag variant='compact' color='red'>Failed</Tag></Tooltip>}
                        </Stack>
                    );
                },
                width: 115,
                maxWidth: 115,
            },
            {
                field: 'metadata',
                headerName: 'Report',
                sortable: false,
                suppressHeaderMenuButton: true,
                suppressHeaderContextMenu: true,
                filter: false,
                cellStyle: {
                    display: 'flex',
                    alignItems: 'center',
                },
                width: 85,
                maxWidth: 85,
                cellRenderer: (params: ICellRendererParams<TestExecution>) => {
                    const runId = params.data?.metadata?.runId;
                    const ssRunId = params.data?.metadata?.ssRunId;

                    const ocgaReportHref = runId
                        ? `https://test2.dta.netflix.net/dashboard/test/?runId=${runId}&preset=cloudgamedev`
                        : '';
                    const ssReportHref = ssRunId
                        ? `https://test2.dta.netflix.net/dashboard/test/?runId=${ssRunId}&preset=cloudgamedev`
                        : '';

                    return (
                        <Stack orientation='horizontal' style={{ alignItems: 'center', justifyContent: 'center' }}>
                            {runId && (
                                <Button
                                    variant='icon'
                                    compact
                                    aria-label='performance-report'
                                    icon={IconDocumentChart}
                                    href={ocgaReportHref}
                                    target='_blank'
                                >
                                    Load Test
                                </Button>
                            )}
                            {ssRunId && (
                                <Button
                                    variant='icon'
                                    compact
                                    icon={IconDocumentChart}
                                    href={ssReportHref}
                                    target='_blank'
                                    aria-label='single-session-report'
                                >
                                    Single Session
                                </Button>
                            )}
                            {!runId && !ssRunId && (
                                <Button
                                    disabled={true}
                                    variant='icon'
                                    aria-label='no-performance-report'
                                    compact
                                    icon={IconDocumentChart}
                                    href={ocgaReportHref}
                                    target='_blank'
                                />
                            )}
                        </Stack>
                    );
                },
            },
            {
                field: 'resolution',
                headerName: 'Resolution',
                sortable: false,
                wrapHeaderText: false,
                cellRenderer: (params: ICellRendererParams<TestExecution, string>) => {
                    return `${params.value || DEFAULT_TEST_RESOLUTION}p`;
                },
                width: 100,
                maxWidth: 100,
            },
            {
                field: 'fps',
                headerName: 'FPS',
                sortable: false,
                cellRenderer: (params: ICellRendererParams<TestExecution, string>) => {
                    return `${params.value || DEFAULT_TEST_FPS}`;
                },
                width: 75,
                maxWidth: 75,
            },
            {
                field: 'metadata',
                headerName: 'Test Duration',
                filter: 'agNumberColumnFilter',
                cellRenderer: (params: ICellRendererParams<TestExecution, string>) => {
                    return params.data?.metadata?.duration
                        ? convertMilliseconds(Number(params.data?.metadata?.duration))
                        : null;
                },
                width: 100,
                maxWidth: 100,
            },
            {
                field: 'autoplayDuration',
                headerName: 'Requested Duration',
                filter: 'agTextColumnFilter',
                cellRenderer: (params: ICellRendererParams<TestExecution, number>) => {
                    // Only show autoplay duration for single session tests
                    if (params.data?.testSuite === TestSuite.SINGLE_SESSION) {
                        return params.data?.autoplayDuration
                            ? convertSecondsToDisplay(params.data.autoplayDuration)
                            : null;
                    }
                    return null;
                },
                width: 115,
                maxWidth: 115,
            },
        ];
    }, []);

    const onRowSelected = useCallback((_event: RowSelectedEvent<TestExecution>) => {
        const selectedNodes = gridRef.current?.api?.getSelectedNodes();
        const selectedData = selectedNodes?.map((node: IRowNode<TestExecution>) => node.data) || [];
        setSelectedTests(selectedData as TestExecution[]);
    }, []);

    const handleDeleteTest = useCallback(async () => {
        setDeleteModalOpen(false);
        if (!gameId) {
            return;
        }

        const testIds = selectedTests.map((test: TestExecution) => {
            return test.id;
        });
        setDeleteExecuting(true);
        const response = await fetch(`api/games/${gameId}/test-executions`, {
            method: 'DELETE',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                testExecutionIds: testIds,
            }),
        });
        setDeleteExecuting(false);
        setSelectedTests([]);
        queryClient.invalidateQueries({ queryKey: [TEST_EXECUTIONS_KEY] });

        return response;
    }, [gameId, selectedTests, queryClient.invalidateQueries]);

    return (
        <Layout full className={styles.testExecutionsLayout}>
            <Content style={{ display: 'flex', flexDirection: 'column', flex: 1 }}>
                <Paper elevation={1} className={styles.headerBanner}>
                    <Dropdown
                        // biome-ignore lint/suspicious/noExplicitAny: Complex DropdownTrigger typing
                        DropdownTrigger={forwardRef((props: any, ref: any) => (
                            <DropdownTrigger {...props} hideSubtitle ref={ref} />
                        ))}
                        label={`Game ID: ${selectedGame?.value ?? ''}`}
                        groupBy={(option) => option.group ?? ''}
                        onChange={(selected) => {
                            if (selected) {
                                setParams(
                                    (prev): SearchParams => {
                                        return {
                                            ...paramsObject(prev),
                                            gameId: selected.value,
                                            channelName: undefined,
                                        };
                                    },
                                    { replace: true },
                                );
                            }
                        }}
                        options={gameOptions}
                        loading={gameOptions.length === 0}
                        value={selectedGame}
                        getOptionValue={(option) => {
                            if (typeof option === 'string') {
                                return option;
                            }
                            return `${option.group}_${option.value}`;
                        }}
                        searchable={gameOptions.length > 5}
                        filterOptions={getFuzzyFilterOption(gameOptions, {
                            keys: ['label', 'subtitle'],
                            ignoreLocation: true,
                        })}
                        key={`games-${keyFromOptions(gameOptions)}`}
                        style={{ maxWidth: 230, width: 'auto' }}
                        dropdownWidthType={350}
                    />

                    <Stack orientation='horizontal' gap={Dimensions.Space8}>
                        {identity.roles.has(Role.NCGT_ADMIN) && (
                            <Button
                                executing={deleteExecuting}
                                icon={IconWarning}
                                disabled={selectedTests.length === 0}
                                onClick={() => setDeleteModalOpen(true)}
                                variant='primary-destructive'
                            >
                                {selectedTests.length > 0
                                    ? `Delete ${selectedTests.length} ${plural('Test', selectedTests.length)}`
                                    : 'Delete Tests'}
                            </Button>
                        )}
                        <Button onClick={onNewTest}>
                            New Test
                        </Button>
                    </Stack>
                </Paper>

                <DeleteTestModal
                    open={deleteModalOpen}
                    selectedIds={selectedTests}
                    onDelete={handleDeleteTest}
                    onClose={() => {
                        setDeleteModalOpen(false);
                    }}
                />

                <NewTestModal
                    open={modalOpen}
                    gameId={selectedGame?.value!}
                    gameName={selectedGame?.label!}
                    onClose={() => {
                        setModalOpen(false);
                    }}
                />

                {error && <Heading level={2}>{error.message || 'Error loading tests'}</Heading>}

                {!error && !isLoading && !filteredTestExecutions?.length && (
                    <Stack gap={Dimensions.Space8}>
                        <Heading level={2}>No test executions available for this game</Heading>
                    </Stack>
                )}

                {(isLoading || filteredTestExecutions?.length > 0) && (
                    <TableNext<TestExecution>
                        gridRef={gridRef}
                        animateRows={true}
                        loading={isLoading}
                        rowHeight='compact'
                        autoGroupColumnDef={autoGroupColumnDef}
                        columnDefs={columnDefs}
                        enableCellTextSelection={true}
                        ensureDomOrder={true}
                        defaultColDef={defaultColDef}
                        groupDefaultExpanded={1}
                        modules={modules}
                        pagination={true}
                        onRowSelected={isNCGTAdmin ? onRowSelected : undefined}
                        rowSelection={isNCGTAdmin ? rowSelection : undefined}
                        paginationPageSize={PAGINATION_PAGE_SIZE}
                        paginationPageSizeSelector={PAGINATION_OPTIONS}
                        rowData={filteredTestExecutions}
                        style={{ height: '100%', width: '100%' }}
                    />
                )}
            </Content>
        </Layout>
    );
};
