import { IconDownloadCircle, IconUpload } from '@hawkins/assets';
import { Button, Stack } from '@hawkins/components';
import { Dimensions } from '@hawkins/variables';
import type { EnvVar } from '@ncgt/common/models/envVar';
import { csvToEnvVars, envVarsToCsv } from '@ncgt/common/utils/envVar';
import { type ChangeEvent, useCallback, useRef } from 'react';
import styles from './EnvVarTable.module.css';

export interface EnvVarTableHeaderActionsProps {
    disabled?: boolean;
    onImport: (vars: EnvVar[]) => void;
    getExportData: () => EnvVar[];
    filename?: string;
}

const triggerCsvDownload = (filename: string, content: string) => {
    const blob = new Blob([content], { type: 'text/csv;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = filename;
    document.body.appendChild(anchor);
    anchor.click();
    document.body.removeChild(anchor);
    URL.revokeObjectURL(url);
};

export const EnvVarTableHeaderActions = ({
    disabled,
    onImport,
    getExportData,
    filename = 'environment-variables.csv',
}: EnvVarTableHeaderActionsProps) => {
    const fileInputRef = useRef<HTMLInputElement>(null);

    const handleUploadClick = useCallback(() => {
        fileInputRef.current?.click();
    }, []);

    const handleFileChange = useCallback(
        async (event: ChangeEvent<HTMLInputElement>) => {
            const file = event.target.files?.[0];
            event.target.value = '';
            if (!file) return;
            try {
                const text = await file.text();
                const { vars, errors } = csvToEnvVars(text);
                if (errors.length) {
                    console.warn('CSV import warnings:', errors);
                }
                onImport(vars);
            } catch (e) {
                console.error('Failed to parse CSV:', e);
            }
        },
        [onImport],
    );

    const handleDownload = useCallback(() => {
        triggerCsvDownload(filename, envVarsToCsv(getExportData()));
    }, [getExportData, filename]);

    return (
        <>
            <Stack orientation='horizontal' gap={Dimensions.Space4}>
                <Button
                    compact
                    variant='icon'
                    icon={IconUpload}
                    disabled={disabled}
                    aria-label='Import Environment Variables, CSV only'
                    tooltipLabel='Import Environment Variables, CSV only'
                    tooltipProps={{ disabled }}
                    onClick={handleUploadClick}
                />
                <Button
                    compact
                    variant='icon'
                    icon={IconDownloadCircle}
                    aria-label='Save the current variables to CSV file'
                    tooltipLabel='Save the current variables to CSV file'
                    onClick={handleDownload}
                />
            </Stack>
            <input
                ref={fileInputRef}
                type='file'
                accept='.csv,text/csv'
                className={styles.hiddenInput}
                onChange={handleFileChange}
            />
        </>
    );
};
