import { useQuery } from '@tanstack/react-query';
import { useEffect } from 'react';

export enum TestSuite {
    OCGAPERF = 'ocgaperf',
    SINGLE_SESSION = 'single_session',
}

export type GameBuild = {
    channel: string;
    gameId: number;
    label: string;
};

export const TEST_EXECUTIONS_KEY = 'testExecutions';

export type TestExecution = {
    id: string;
    build: GameBuild;
    buildId: string;
    buildLabel: string;
    state: string;
    testSuite?: TestSuite;
    metadata: any;
    createdDate: string;
    createdBy?: string;
    fps?: number;
    resolution?: number;
    autoplayDuration?: number;
};

const fetchTestExecutions = async (gameId: string | undefined): Promise<TestExecution[] | undefined> => {
    const response = await fetch(`/api/games/${gameId}/test-executions`, {
        headers: {
            'Content-Type': 'application/json',
        },
    });
    if (!response.ok) {
        const errorData = await response.text();
        let errorMessage = `Fetch failed with status ${response.status}: ${errorData}`;
        try {
            const errorJson = JSON.parse(errorData);
            if (errorJson.message) {
                errorMessage = errorJson.message;
            }
        } catch (_error) {}
        throw new Error(errorMessage);
    }
    return response.json() as Promise<TestExecution[]>;
};

export function useTestExecutions(gameId: string | undefined) {
    const query = useQuery({
        queryKey: [TEST_EXECUTIONS_KEY, gameId],
        meta: {
            pollIntervalMs: 30000,
        },
        enabled: Boolean(gameId),
        queryFn: () => fetchTestExecutions(gameId),
    });

    const { error, isError } = query;
    useEffect(() => {
        if (isError) {
            console.error(`Error getting test executions. ${error?.message}`);
        }
    }, [error, isError]);

    return query;
}
